<?php
namespace App\Http\Controllers\Api;use App\Domain\Accounting\Services\AccountingReportService;use App\Http\Controllers\Controller;use App\Services\Accounting\AccountingContext;use Illuminate\Http\Request;
class TrialBalanceController extends Controller{public function index(Request $r,AccountingReportService $s,AccountingContext $c){$v=$r->validate(['financial_year_id'=>'nullable|integer','from_date'=>'nullable|date','to_date'=>'nullable|date|after_or_equal:from_date']);try{return response()->json(['status'=>true,'data'=>$s->trialBalance($c->companyId($r),$c->branchFilter($r),$v)]);}catch(\Throwable$e){return response()->json(['status'=>false,'message'=>$e->getMessage()],422);}}}
